import React, { useState, useEffect } from "react";
import { Link, useNavigate } from 'react-router-dom';
import axios from 'axios';
import Sidebar from "../../components/Sidebar_p-a";
import HeaderProductos from "../../components/HeaderProductos";
import "../../components/admin.css";

const API_URL = "http://localhost:3001/api/productos";

export default function Productos(){
    const [productos, setProductos] = useState([]);
    const [cargando, setCargando] = useState(true);
    const [error, setError] = useState(null);
    const navigate = useNavigate();

    const fetchProductos = async () => {
        try {
            setCargando(true);
            const response = await axios.get(API_URL);
            setProductos(response.data); 
            setError(null);
        } catch (err) {
            console.error("Error al cargar los productos:", err);
            setError("Error al cargar los productos. Por favor, intente de nuevo más tarde.");
        } finally {
            setCargando(false);
        }
    };

    useEffect(() => {
        fetchProductos();
    }, []);

    const handleEditar = (producto) => {
        console.log("✏️ Editando producto:", producto);
        // Navega al formulario de edición pasando el producto en el state
        navigate(`/editar_producto/${producto.id_producto}`, { 
            state: { producto } 
        });
    };

    const handleEliminar = async (id_producto) => {
        const confirmar = window.confirm(
            "¿Estás seguro de que deseas eliminar este producto? Esta acción no se puede deshacer."
        );
        
        if (!confirmar) return;

        try {
            console.log("🗑️ Eliminando producto ID:", id_producto);
            await axios.delete(`${API_URL}/${id_producto}`);
            
            // Actualizar la lista después de eliminar
            setProductos(productos.filter(p => p.id_producto !== id_producto));
            
            alert("Producto eliminado con éxito");
        } catch (error) {
            console.error("Error al eliminar:", error);
            alert("Error al eliminar el producto: " + (error.response?.data?.error || error.message));
        }
    };

    if (cargando) {
        return (
            <div className="dashboard-layout">
                <Sidebar />
                <main className="contenido">
                    <HeaderProductos /> 
                    <div style={{ padding: '40px', textAlign: 'center' }}>
                        <p>⏳ Cargando productos...</p>
                    </div>
                </main>
            </div>
        );
    }

    if (error) {
        return (
            <div className="dashboard-layout">
                <Sidebar />
                <main className="contenido">
                    <HeaderProductos /> 
                    <div style={{ padding: '40px', textAlign: 'center', color: 'red' }}>
                        <p>{error}</p>
                        <button onClick={fetchProductos}>Reintentar</button>
                    </div>
                </main>
            </div>
        );
    }

    return(
        <div className="dashboard-layout">
            <Sidebar />

            <main className="contenido">
                <HeaderProductos /> 

                <section className="cuadro-blanco">
                    <div className="acciones">
                        <button className="btn-categoria">Confecciones</button> 
                        <input type="text" placeholder="Filtrar categoria" className="buscar" /> 

                        <Link to="/registro_prod" className="registrar">
                            <button className="btn-registrar">
                                Registrar nuevo Producto
                            </button>
                        </Link>
                    </div>

                    <table className="tabla">
                        <thead>
                            <tr>
                                <th>ID</th>
                                <th>Imagen</th>
                                <th>Producto</th>
                                <th>Categoria</th>
                                <th>Clasificación</th>
                                <th>Descripción</th>
                                <th>Precio</th>
                                <th>Stock</th>
                                <th>Acciones</th>
                            </tr>
                        </thead>
                        
                        <tbody>
                            {productos.length === 0 ? (
                                <tr>
                                    <td colSpan="9" style={{ textAlign: 'center', padding: '40px' }}>
                                        No hay productos registrados
                                    </td>
                                </tr>
                            ) : (
                                productos.map((producto) => (
                                    <tr key={producto.id_producto}>
                                        <td>{producto.id_producto}</td>

                                        <td>
                                            {producto.ruta_imagen ? (
                                                <img 
                                                    src={`http://localhost:3001${producto.ruta_imagen}`} 
                                                    alt={producto.nom_producto} 
                                                    style={{ 
                                                        width: '50px', 
                                                        height: '50px', 
                                                        objectFit: 'cover',
                                                        borderRadius: '4px'
                                                    }}
                                                />
                                            ) : (
                                                <span style={{ color: '#999' }}>Sin imagen</span>
                                            )}
                                        </td>

                                        <td>{producto.nom_producto}</td>
                                        <td>{producto.nombre_c || producto.id_categoria}</td>
                                        <td>{producto.nombre_clas || producto.id_clasificacion}</td>
                                        <td>{producto.descripcion || '-'}</td>
                                        <td>${parseFloat(producto.precio_unitario).toFixed(2)}</td>
                                        <td>
                                            <span style={{
                                                padding: '4px 8px',
                                                borderRadius: '4px',
                                                backgroundColor: producto.stock_actual <= producto.stock_minimo ? '#ffebee' : '#e8f5e9',
                                                color: producto.stock_actual <= producto.stock_minimo ? '#c62828' : '#2e7d32',
                                                fontWeight: 'bold'
                                            }}>
                                                {producto.stock_actual}
                                            </span>
                                        </td>
                                        <td>
                                            <button 
                                                onClick={() => handleEditar(producto)}
                                                className="editar"
                                                style={{ 
                                                    marginRight: '5px',
                                                    cursor: 'pointer'
                                                }}
                                            >
                                                Editar
                                            </button>
                                            <button 
                                                onClick={() => handleEliminar(producto.id_producto)}
                                                className="eliminar"
                                                style={{ cursor: 'pointer' }}
                                            >
                                                Eliminar
                                            </button>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </section>
            </main>
        </div> 
    );
}
